//! Wraps MIT bvh0.13 serial binned-SAH build and contiguous FlatBvh traversal.
//! Original stream adapter/bounds/budgets/query verification. No SAH port copied.
#[cfg(feature="flat-sah")]
mod enabled{
use super::super::{vertex_stream::Stream,spatial::{Ray,Hit}};use bvh::{aabb::{Aabb,Bounded},bounding_hierarchy::{BHShape,BoundingHierarchy},bvh::Bvh,flat_bvh::FlatBvh};use nalgebra::{Point3,Vector3};
#[derive(Clone)]struct Triangle{points:[Point3<f64>;3],bounds:Aabb<f64,3>,node:usize,id:usize}
impl Bounded<f64,3> for Triangle{fn aabb(&self)->Aabb<f64,3>{self.bounds}}
impl BHShape<f64,3> for Triangle{fn set_bh_node_index(&mut self,i:usize){self.node=i;}fn bh_node_index(&self)->usize{self.node}}
pub struct Index{shapes:Vec<Triangle>,flat:FlatBvh<f64,3>}
impl Index{
 pub fn build(s:&Stream)->Result<Self,String>{s.validate()?;if s.indices.len()>100_000{return Err("flat SAH draft max100000 triangles".into());}crate::guard::reserve(s.indices.len()*1024);let mut shapes=Vec::with_capacity(s.indices.len());for(id,tri)in s.indices.iter().enumerate(){let p=tri.map(|i|Point3::from(s.vertices[i as usize].position.map(|v|v as f64)));let lo=Point3::from(std::array::from_fn(|j|p.iter().map(|p|p[j]).fold(f64::INFINITY,f64::min)));let hi=Point3::from(std::array::from_fn(|j|p.iter().map(|p|p[j]).fold(f64::NEG_INFINITY,f64::max)));shapes.push(Triangle{points:p,bounds:Aabb::with_bounds(lo,hi),node:0,id});}let tree=Bvh::build(&mut shapes);let flat=tree.flatten();drop(tree);Ok(Self{shapes,flat})}
 pub fn inspect(&self)->serde_json::Value{serde_json::json!({"triangles":self.shapes.len(),"flat_nodes":self.flat.len(),"node_bytes":std::mem::size_of::<bvh::flat_bvh::FlatNode<f64,3>>(),"builder":"bvh0.13 serial binned SAH","query_layout":"contiguous FlatBvh escape indices","parallel_build":false,"memory_peak_measured":false})}
 fn ray(r:&Ray)->Result<bvh::ray::Ray<f64,3>,String>{if r.origin.iter().chain(r.direction.iter()).chain([r.t_min,r.t_max].iter()).any(|v|!v.is_finite()||v.abs()>1e9)||r.direction.iter().all(|v|*v==0.)||r.t_min<0.||r.t_max<r.t_min{return Err("bounded finite ray0<=t_min<=t_max required".into());}{let mut d=r.direction;for c in d.iter_mut(){if *c==0.{*c=1e-12;}}Ok(bvh::ray::Ray::new(Point3::from(r.origin),Vector3::from(d)))}}
 fn hit(ray:&bvh::ray::Ray<f64,3>,t:&Triangle,r:&Ray)->Option<Hit>{let front=ray.intersects_triangle(&t.points[0],&t.points[1],&t.points[2]);let back=ray.intersects_triangle(&t.points[0],&t.points[2],&t.points[1]);let (distance,u,v)=if front.distance<=back.distance{(front.distance,front.u,front.v)}else{(back.distance,back.v,back.u)};if !distance.is_finite()||distance<r.t_min||distance>r.t_max{return None;}Some(Hit{triangle:t.id,t:distance,barycentric:[1.-u-v,u,v]})}
 pub fn raycast(&self,r:&Ray,brute:bool)->Result<Option<Hit>,String>{self.raycast_where(r,brute,|_|true)}
 pub fn raycast_where(&self,r:&Ray,brute:bool,accept:impl Fn(usize)->bool)->Result<Option<Hit>,String>{let ray=Self::ray(r)?;let mut best:Option<Hit>=None;let candidates=if brute{self.shapes.iter().collect::<Vec<_>>()}else{self.flat.traverse(&ray,&self.shapes)};for t in candidates{if !accept(t.id){continue;}if let Some(h)=Self::hit(&ray,t,r){if best.as_ref().map(|b|h.t<b.t||h.t==b.t&&h.triangle<b.triangle).unwrap_or(true){best=Some(h);}}}Ok(best)}
 pub fn cull_aabb(&self,bounds:[[f64;3];2])->Result<Vec<usize>,String>{if bounds.iter().flatten().any(|v|!v.is_finite())||(0..3).any(|j|bounds[0][j]>bounds[1][j]){return Err("finite ordered AABB".into());}let q=Aabb::with_bounds(Point3::from(bounds[0]),Point3::from(bounds[1]));let mut ids=self.flat.traverse(&q,&self.shapes).iter().map(|s|s.id).collect::<Vec<_>>();ids.sort_unstable();Ok(ids)}
}
#[cfg(test)]mod tests{use super::*;use crate::threed::primitives::{generate,Primitive};fn s()->Stream{let g=generate(&Primitive::Cube{size:[1.;3],subdivisions:4}).unwrap();Stream{vertices:g.vertices,indices:g.indices}}
#[test]fn ray_jitter_f64_stays_finite_nonzero_and_hit_distance_unchanged(){for d in [[0.,0.,1.],[0.,1.,0.],[1.,0.,0.],[0.,0.,-1.],[1.,1.,1.]]{let r=Ray{origin:[0.,0.,-2.],direction:d,t_min:0.,t_max:5.};let br=Index::ray(&r).unwrap();assert!(br.direction.iter().all(|v|v.is_finite()&&*v!=0.),"direction {d:?}");assert!(br.inv_direction.iter().all(|v|v.is_finite()),"inv {d:?}");assert!(br.origin.iter().all(|v|v.is_finite()));}let stream=s();let b=Index::build(&stream).unwrap();let r=Ray{origin:[0.,0.,-2.],direction:[0.,0.,1.],t_min:0.,t_max:5.};let h=b.raycast(&r,true).unwrap().unwrap();assert!((h.t-1.5).abs()<1e-9,"t={}",h.t);}
#[test]fn flat_rays_aabb_and_degenerate_rejection(){let stream=s();let b=Index::build(&stream).unwrap();for x in -8..=8{let r=Ray{origin:[x as f64/8.,0.,-2.],direction:[0.,0.,1.],t_min:0.,t_max:5.};let a=b.raycast(&r,false).unwrap();let c=b.raycast(&r,true).unwrap();assert_eq!(a.as_ref().map(|h|h.triangle),c.as_ref().map(|h|h.triangle));}assert_eq!(b.cull_aabb([[-1.;3],[1.;3]]).unwrap().len(),stream.indices.len());assert!(b.cull_aabb([[5.;3],[6.;3]]).unwrap().is_empty());let mut bad=stream;bad.indices[0]=[0,0,0];assert!(Index::build(&bad).is_err());}
}
}
#[cfg(feature="flat-sah")]pub use enabled::Index;
